bool oom_reap_task_memory(struct task_struct *tsk, struct mm_struct *mm)
{
    bool success = false;
    int ret;

    mutex_lock(&mm->mmap_lock);
    ret = down_read_trylock(&mm->mmap_sem);
    if (!ret) {
        mutex_unlock(&mm->mmap_lock);
        return false;
    }

    if (atomic_read(&mm->mm_count) > 1)
        schedule();

    if (mm->flags & MMF_OOM_SKIP) {
        up_read(&mm->mmap_sem);
        mutex_unlock(&mm->mmap_lock);
        return false;
    }

    mm->flags |= MMF_OOM_SKIP;
    mm->oom_skip_count++;

    struct vm_area_struct *vma;
    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & (VM_ANON | VM_SHARED))
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
    }

    success = true;

    up_read(&mm->mmap_sem);
    mutex_unlock(&mm->mmap_lock);

    return success;
}

bool oom_reap_task(struct task_struct *tsk, struct mm_struct *mm) {
    bool success = false;
    down_read(&mm->mmap_lock);

    if (unlikely(!try_read_lock(&mm->mmap_lock))) {
        pr_info("Failed to acquire read lock on memory map semaphore.\n");
        goto out_unlock;
    }

    if (atomic_read(&mm->mm_count) > 1) {
        schedule();
    }

    if (test_bit(MMF_OOM_SKIP, &mm->flags)) {
        pr_info("OOM reaping skipped for task %d.\n", tsk->pid);
        goto out_unlock;
    }

    set_bit(MMF_OOM_SKIP, &mm->flags);

    struct vm_area_struct *vma;
    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    pr_info("Reaped memory for task %d (PID: %d)\n", tsk->pid, tsk->pid);
    success = true;

out_unlock:
    up_read(&mm->mmap_lock);
    return success;
}

#include <linux/mutex.h>
#include <linux/mm.h>
#include <linux/oom.h>
#include <linux/sched.h>
#include <linux/printk.h>

bool oom_reap_task(struct task_struct *tsk, struct mm_struct *mm) {
    int ret = false;
    struct vm_area_struct *vma, *prev_vma = NULL;

    mutex_lock(&mm->mmap_mutex);

    if (down_read_trylock(&mm->mmap_sem) != 1) {
        pr_info("Failed to acquire read lock on mmap semaphore.\n");
        mutex_unlock(&mm->mmap_mutex);
        return false;
    }

    if (atomic_read(&mm->mm_count) && (mm->flags & MMF_OOM_SKIP)) {
        pr_info("Reaping skipped due to OOM_SKIP flag.\n");
        up_read(&mm->mmap_sem);
        mutex_unlock(&mm->mmap_mutex);
        return false;
    }

    mm->flags |= MMF_OOM_SKIP;

    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    pr_info("Reaped memory from task PID %d.\n", tsk->pid);

    up_read(&mm->mmap_sem);
    mutex_unlock(&mm->mmap_mutex);

    return true;
}

bool reap_memory_on_oom(struct task_struct *tsk, struct mm_struct *mm) {
    bool success = false;

    mutex_lock(&mm->mmap_lock);

    if (!down_read_trylock(&mm->mmap_sem)) {
        pr_info("Failed to acquire read lock on memory map semaphore.\n");
        goto out_unlock_mutex;
    }

    if (atomic_read(&mm->mm_users)) {
        pr_info("Yielding to allow OOM victim more time.\n");
        schedule_timeout_uninterruptible(HZ / 10);
    }

    if (mm->flags & MMF_OOM_SKIP) {
        pr_info("Reaping is skipped for the current memory management structure.\n");
        goto out_unlock_sem;
    }

    mm->flags |= MMF_OOM_REAPING;
    mm->oom_stable = false;

    for (struct vm_area_struct *vma = mm->mmap; vma; vma = vma->vm_next) {
        if ((vma->vm_flags & (VM_ANON | VM_SHARED)) == VM_ANON) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    pr_info("Successfully reaped memory for task %d.\n", tsk->pid);
    success = true;

out_unlock_sem:
    up_read(&mm->mmap_sem);
out_unlock_mutex:
    mutex_unlock(&mm->mmap_lock);

    return success;
}

bool oom_reap_task(struct task_struct *tsk, struct mm_struct *mm)
{
    bool ret = false;
    int vma_idx;

    mutex_lock(&mm->mmap_lock);
    if (!down_read_trylock(&mm->mmap_sem)) {
        pr_info("Failed to acquire read lock on memory map semaphore.\n");
        goto out_unlock;
    }

    if (atomic_read(&mm->oom_notifiers)) {
        cond_resched();
    }

    if (test_bit(MMF_OOM_SKIP, &mm->flags)) {
        pr_info("Memory is marked for OOM skip. Reaping not allowed.\n");
        goto out_unlock_lock;
    }

    set_bit(MMF_OOM_SKIP, &mm->flags);

    for (vma_idx = 0; vma_idx < mm->map_count; ++vma_idx) {
        struct vm_area_struct *vma = mm->mmap[vma_idx];
        if (vma && (vma->vm_flags & (VM_ANON | VM_SHARED))) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    pr_info("OOM reaped task %d (pid), memory marked unstable.\n", tsk->pid);
    ret = true;

out_unlock_lock:
    up_read(&mm->mmap_sem);
out_unlock:
    mutex_unlock(&mm->mmap_lock);

    return ret;
}
